pub fn get_opening_move(partial_zobrist: u64) -> Option<CompactMove> {

    let index_main: usize = (partial_zobrist.wrapping_mul(MAGIC_MAIN) >> SHIFT_MAIN) as usize;
    let magic: u64 = MAGICS[index_main];
    let index: usize = (partial_zobrist.wrapping_mul(magic) >> SHIFT_BUCKET) as usize;

    if let Some(info) = OPENING_BOOK[index_main][index] {
        let total_moves = info.0;
        let moves = info.1;

        // If there is only one option, we take that option
        if moves.len() == 1 {
            return Some(moves[0].0)
        }

        // If there is more than one option, we pick randomly but proportional to the percentage of moves compared to the total moves
        let mut rng = rand::rng();
        let random_number = rng.random_range(0..total_moves);

        let mut cumulative = 0u32;

        for &(move1, count) in moves {
            cumulative += count;
            if random_number < cumulative {
                return Some(move1);
            }
        }

        panic!("get_opening_move: cumulative sum is smaller than total_moves")
    } else {
        None
    }
}

